bool square(long long n){if(n<0)return false;long long d=sqrtl(n);return d*d==n||(d+1)*(d+1)==n;}
void row(const vector<long long>&a){for(size_t i=0;i<a.size();i++){if(i)cout<<' ';cout<<a[i];}cout<<'\n';}
void printMat(const Mat&a){for(auto&r:a)row(r);}
